"""Price quotes for the carriers the shop ships with."""


# courier -> (label, heaviest parcel in g, base price, weight step in g, price per step, zone fee, signature fee, fragile fee, fuel %)
_RATES = {
    "northwind": ("Northwind", 20000, 390, 2000, 150, 100, 0, 0, 0),
    "arrowhead": ("Arrowhead", 5000, 450, 500, 120, 150, 120, 0, 0),
    "lantern": ("Lantern", 20000, 520, 1000, 120, 150, 0, 350, 0),
    "pelican": ("Pelican", 10000, 390, 500, 150, 150, 200, 350, 0),
    "brisk": ("Brisk", 20000, 390, 1000, 150, 100, 120, 0, 0),
}


def _quote(courier, parcel):
    label, max_g, base, step_g, step_price, zone_fee, sig_fee, fragile, fuel = _RATES[courier]
    weight = parcel["weight_g"]
    if weight <= 0 or weight > max_g:
        raise ValueError("%s cannot carry %d g" % (label, weight))
    price = base
    if weight > step_g:
        price += (weight - step_g + step_g - 1) // step_g * step_price
    if parcel.get("zone", 1) > 1:
        price += zone_fee * (parcel["zone"] - 1)
    if parcel.get("signature"):
        price += sig_fee
    if fragile and parcel.get("fragile"):
        price += fragile
    if fuel:
        price = price * (100 + fuel) // 100
    return {"carrier": label, "cents": price}


def quote_northwind(parcel):
    """Quote a parcel with Northwind."""
    return _quote("northwind", parcel)

def quote_arrowhead(parcel):
    """Quote a parcel with Arrowhead."""
    return _quote("arrowhead", parcel)

def quote_lantern(parcel):
    """Quote a parcel with Lantern."""
    return _quote("lantern", parcel)

def quote_pelican(parcel):
    """Quote a parcel with Pelican."""
    return _quote("pelican", parcel)

def quote_brisk(parcel):
    """Quote a parcel with Brisk."""
    return _quote("brisk", parcel)

