import json
import unittest

import importlib

def run_case(case):
    mod = importlib.import_module("parcelpost.quotes")
    return getattr(mod, case["fn"])(*case["args"])

def norm(x):
    return json.loads(json.dumps(x))


class QuotesTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"fn\": \"quote_northwind\", \"args\": [{\"weight_g\": 1}]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"carrier\": \"Northwind\", \"cents\": 390}"))

    def test_example_2(self):
        case = json.loads("{\"fn\": \"quote_arrowhead\", \"args\": [{\"weight_g\": 400, \"fragile\": true}]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"carrier\": \"Arrowhead\", \"cents\": 450}"))

    def test_example_3(self):
        case = json.loads("{\"fn\": \"quote_northwind\", \"args\": [{\"weight_g\": 500}]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"carrier\": \"Northwind\", \"cents\": 390}"))

    def test_error_example(self):
        case = json.loads("{\"fn\": \"quote_arrowhead\", \"args\": [{\"weight_g\": 15000, \"zone\": 3}]}")
        with self.assertRaises(Exception) as caught:
            run_case(case)
        self.assertEqual(type(caught.exception).__name__, 'ValueError')


if __name__ == '__main__':
    unittest.main()

