"""Text lines for the community garden activity feed."""


# kind -> (actor key, target key, verb, text without a target, icon, show a repeat count)
_KINDS = {
    "watering": ("who", "plot", "watered", "watered the beds", "~", False),
    "compost": ("gardener", "what", "turned", "turned the compost", "C", False),
    "planting": ("who", "bed", "planted", "planted something", "S", False),
    "tool": ("gardener", "plot", "borrowed", "borrowed a tool", "T", False),
    "weeding": ("gardener", "what", "weeded", "weeded the plots", "W", True),
    "harvest": ("who", "what", "picked", "went harvesting", "H", False),
}


def _format(kind, event):
    actor_key, target_key, verb, verb_none, icon, show_count = _KINDS[kind]
    actor = event.get(actor_key) or "someone"
    target = event.get(target_key)
    if target is None:
        text = "%s %s" % (actor, verb_none)
    else:
        text = "%s %s %s" % (actor, verb, target)
    if show_count and event.get("count", 1) > 1:
        text += " (x%d)" % event["count"]
    minutes = event.get("at", 0) // 60 % 1440
    stamp = "%02d:%02d" % (minutes // 60, minutes % 60)
    if event.get("urgent"):
        text = text.upper()
    return "[%s] %s %s" % (stamp, icon, text)


def format_watering(event):
    """Render a watering event for the activity feed."""
    return _format("watering", event)

def format_compost(event):
    """Render a compost event for the activity feed."""
    return _format("compost", event)

def format_planting(event):
    """Render a planting event for the activity feed."""
    return _format("planting", event)

def format_tool(event):
    """Render a tool event for the activity feed."""
    return _format("tool", event)

def format_weeding(event):
    """Render a weeding event for the activity feed."""
    return _format("weeding", event)

def format_harvest(event):
    """Render a harvest event for the activity feed."""
    return _format("harvest", event)

