def sample(stock, sku, qty, note=""):
    """Take a germination sample."""
    if qty <= 0:
        raise ValueError("quantity must be positive")
    item = stock["items"].get(sku)
    if item is None:
        raise KeyError(sku)
    delta = -1 * qty
    if item["on_hand"] + delta < 0:
        raise ValueError("not enough stock for %s" % sku)
    item["on_hand"] += delta
    stock["moves"].append({"sku": sku, "kind": "sample", "qty": delta, "note": note})
    return item["on_hand"]


def return_lot(stock, sku, qty, note=""):
    """Put back seed that was not used."""
    if qty <= 0:
        raise ValueError("quantity must be positive")
    item = stock["items"].get(sku)
    if item is None:
        raise KeyError(sku)
    delta = 1 * qty
    if item["on_hand"] + delta < 0:
        raise ValueError("not enough stock for %s" % sku)
    item["on_hand"] += delta
    stock["moves"].append({"sku": sku, "kind": "return_lot", "qty": delta, "note": note})
    return item["on_hand"]


def discard(stock, sku, qty, note=""):
    """Write off seed that failed germination."""
    if qty <= 0:
        raise ValueError("quantity must be positive")
    item = stock["items"].get(sku)
    if item is None:
        raise KeyError(sku)
    if not note:
        raise ValueError("a note is required")
    delta = -1 * qty
    if item["on_hand"] + delta < 0:
        raise ValueError("not enough stock for %s" % sku)
    item["on_hand"] += delta
    stock["moves"].append({"sku": sku, "kind": "discard", "qty": delta, "note": note})
    return item["on_hand"]

