"""Stock movements for the seed bank inventory."""


# kind -> (sign, lowest allowed on-hand, note required, remember the move number)
_MOVES = {
    "sow": (-1, 0, False, False),
    "return_lot": (1, 0, False, False),
    "discard": (-1, 0, True, False),
    "sample": (-1, 0, False, False),
    "receive": (1, 0, False, True),
    "donate": (-1, 0, True, False),
}


def _move(kind, stock, sku, qty, note):
    sign, floor, need_note, stamp = _MOVES[kind]
    if qty <= 0:
        raise ValueError("quantity must be positive")
    item = stock["items"].get(sku)
    if item is None:
        raise KeyError(sku)
    if need_note and not note:
        raise ValueError("a note is required")
    delta = sign * qty
    if item["on_hand"] + delta < floor:
        raise ValueError("not enough stock for %s" % sku)
    item["on_hand"] += delta
    stock["moves"].append({"sku": sku, "kind": kind, "qty": delta, "note": note})
    if stamp:
        item["last_move"] = len(stock["moves"])
    return item["on_hand"]


def sow(stock, sku, qty, note=""):
    """Take seed out for sowing."""
    return _move("sow", stock, sku, qty, note)

def return_lot(stock, sku, qty, note=""):
    """Put back seed that was not used."""
    return _move("return_lot", stock, sku, qty, note)

def discard(stock, sku, qty, note=""):
    """Write off seed that failed germination."""
    return _move("discard", stock, sku, qty, note)

def sample(stock, sku, qty, note=""):
    """Take a germination sample."""
    return _move("sample", stock, sku, qty, note)

def receive(stock, sku, qty, note=""):
    """Add seed lots that arrived at the bank."""
    return _move("receive", stock, sku, qty, note)

def donate(stock, sku, qty, note=""):
    """Give seed to another bank."""
    return _move("donate", stock, sku, qty, note)

