        self.assertEqual(norm(run_case(case)), json.loads("{\"result\": 1350, \"state\": {\"members\": {\"bo\": {\"credit\": 1500}, \"cy\": {\"credit\": 150}, \"ada\": {\"credit\": 50}}, \"journal\": [[\"cy\", \"printer3d\", 15, -1350]]}}"))

    def test_example_2(self):
        case = json.loads("{\"fn\": \"bill_sewing\", \"state\": {\"members\": {\"cy\": {\"credit\": 50}, \"bo\": {\"credit\": 1500}, \"eli\": {\"credit\": 400}}, \"journal\": []}, \"args\": [\"bo\", 5]}")
