import json
import unittest

import importlib

def run_case(case):
    mod = importlib.import_module("seedbank.moves")
    state = case["state"]
    res = getattr(mod, case["fn"])(state, *case["args"])
    return {"result": res, "state": state}

def norm(x):
    return json.loads(json.dumps(x))


class MovesTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"fn\": \"discard\", \"state\": {\"items\": {\"leek-03\": {\"on_hand\": 10}, \"oat-22\": {\"on_hand\": 50}, \"kale-07\": {\"on_hand\": 3}}, \"moves\": []}, \"args\": [\"leek-03\", 1]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"result\": 9, \"state\": {\"items\": {\"leek-03\": {\"on_hand\": 9}, \"oat-22\": {\"on_hand\": 50}, \"kale-07\": {\"on_hand\": 3}}, \"moves\": [{\"sku\": \"leek-03\", \"kind\": \"discard\", \"qty\": -1, \"note\": \"\"}]}}"))

    def test_example_2(self):
        case = json.loads("{\"fn\": \"receive\", \"state\": {\"items\": {\"oat-22\": {\"on_hand\": 50}, \"bean-01\": {\"on_hand\": 0}, \"kale-07\": {\"on_hand\": 0}}, \"moves\": []}, \"args\": [\"bean-01\", 7]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"result\": 7, \"state\": {\"items\": {\"oat-22\": {\"on_hand\": 50}, \"bean-01\": {\"on_hand\": 7}, \"kale-07\": {\"on_hand\": 0}}, \"moves\": [{\"sku\": \"bean-01\", \"kind\": \"receive\", \"qty\": 7, \"note\": \"\"}]}}"))

    def test_example_3(self):
        case = json.loads("{\"fn\": \"sow\", \"state\": {\"items\": {\"leek-03\": {\"on_hand\": 0}, \"kale-07\": {\"on_hand\": 0}, \"bean-01\": {\"on_hand\": 3}}, \"moves\": []}, \"args\": [\"bean-01\", 2, \"\"]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"result\": 1, \"state\": {\"items\": {\"leek-03\": {\"on_hand\": 0}, \"kale-07\": {\"on_hand\": 0}, \"bean-01\": {\"on_hand\": 1}}, \"moves\": [{\"sku\": \"bean-01\", \"kind\": \"sow\", \"qty\": -2, \"note\": \"\"}]}}"))

    def test_error_example(self):
        case = json.loads("{\"fn\": \"sample\", \"state\": {\"items\": {\"kale-07\": {\"on_hand\": 0}, \"leek-03\": {\"on_hand\": 50}, \"bean-01\": {\"on_hand\": 50}}, \"moves\": []}, \"args\": [\"leek-03\", 60]}")
        with self.assertRaises(Exception) as caught:
            run_case(case)
        self.assertEqual(type(caught.exception).__name__, 'ValueError')


