"""Time-on-machine billing for the makerspace credit ledger."""


class InsufficientCredit(Exception):
    def __init__(self, member, needed):
        super().__init__("%s needs %d more credit" % (member, needed))
        self.member = member
        self.needed = needed


# machine -> (rate per minute, minimum fee, longest session in minutes or None, fee cap or None)
_MACHINES = {
    "sewing": (25, 500, None, None),
    "lathe": (60, 100, None, None),
    "soldering": (90, 300, 240, 2500),
    "kiln": (25, 300, 240, 4000),
}


def _bill(machine, ledger, member, minutes):
    rate, min_fee, limit, cap = _MACHINES[machine]
    account = ledger["members"].get(member)
    if account is None:
        raise KeyError(member)
    if minutes <= 0:
        raise ValueError("minutes must be positive")
    if limit is not None and minutes > limit:
        raise ValueError("%s sessions are limited to %d minutes" % (machine, limit))
    fee = max(minutes * rate, min_fee)
    if cap is not None:
        fee = min(fee, cap)
    if account["credit"] < fee:
        raise InsufficientCredit(member, fee)
    account["credit"] -= fee
    ledger["journal"].append((member, machine, minutes, -fee))
    return fee


def bill_sewing(ledger, member, minutes):
    """Charge a member for time on the sewing machine."""
    return _bill("sewing", ledger, member, minutes)

def bill_lathe(ledger, member, minutes):
    """Charge a member for time on the lathe machine."""
    return _bill("lathe", ledger, member, minutes)

def bill_soldering(ledger, member, minutes):
    """Charge a member for time on the soldering machine."""
    return _bill("soldering", ledger, member, minutes)

def bill_kiln(ledger, member, minutes):
    """Charge a member for time on the kiln machine."""
    return _bill("kiln", ledger, member, minutes)

