"""Retry runners for the integration jobs."""


# policy -> (retryable error, attempts, first delay, growth factor, longest delay, record attempts on the job)
_POLICIES = {
    "mailer": (OSError, 4, 10, 2, 20, False),
    "cache_fill": (LookupError, 6, 5, 2, 120, False),
    "flaky_api": (ConnectionError, 6, 5, 2, 120, False),
    "slow_disk": (TimeoutError, 4, 2, 3, 20, False),
}


def _run(policy, job, attempt_fn, sleep):
    exc, tries, delay, factor, max_delay, log = _POLICIES[policy]
    for attempt in range(1, tries + 1):
        if log:
            job.setdefault("history", []).append(attempt)
        try:
            return attempt_fn(job, attempt)
        except exc:
            if attempt == tries:
                raise
            sleep(delay)
            delay = min(delay * factor, max_delay)


def run_mailer(job, attempt_fn, sleep):
    """Run a mailer job, retrying transient failures."""
    return _run("mailer", job, attempt_fn, sleep)

def run_cache_fill(job, attempt_fn, sleep):
    """Run a cache fill job, retrying transient failures."""
    return _run("cache_fill", job, attempt_fn, sleep)

def run_flaky_api(job, attempt_fn, sleep):
    """Run a flaky api job, retrying transient failures."""
    return _run("flaky_api", job, attempt_fn, sleep)

def run_slow_disk(job, attempt_fn, sleep):
    """Run a slow disk job, retrying transient failures."""
    return _run("slow_disk", job, attempt_fn, sleep)

