import json
import unittest

import importlib

def run_case(case):
    mod = importlib.import_module("parcelpost.quotes")
    return getattr(mod, case["fn"])(*case["args"])

def norm(x):
    return json.loads(json.dumps(x))


class QuotesTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"fn\": \"quote_pelican\", \"args\": [{\"weight_g\": 501}]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"carrier\": \"Pelican\", \"cents\": 610}"))

    def test_example_2(self):
        case = json.loads("{\"fn\": \"quote_lantern\", \"args\": [{\"weight_g\": 1001, \"zone\": 3}]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"carrier\": \"Lantern\", \"cents\": 690}"))

    def test_example_3(self):
        case = json.loads("{\"fn\": \"quote_northwind\", \"args\": [{\"weight_g\": 999, \"zone\": 3, \"fragile\": true}]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"carrier\": \"Northwind\", \"cents\": 1091}"))

    def test_error_example(self):
        case = json.loads("{\"fn\": \"quote_northwind\", \"args\": [{\"weight_g\": 15000, \"fragile\": true}]}")
        with self.assertRaises(Exception) as caught:
            run_case(case)
        self.assertEqual(type(caught.exception).__name__, 'ValueError')


if __name__ == '__main__':
    unittest.main()
